using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using NPOI.HWPF.Extractor;
namespace Ansary;
public sealed record PlainHeading(int Index,int Level,string Text);
public static class TextFormats {
 public static bool Supported(string path)=>Path.GetExtension(path).ToLowerInvariant() is ".docx" or ".doc" or ".txt" or ".md" or ".markdown";
 public static bool Markdown(string path)=>Path.GetExtension(path).ToLowerInvariant() is ".md" or ".markdown";
 public static string[] Read(string path){string extension=Path.GetExtension(path).ToLowerInvariant();if(extension is not (".doc" or ".txt" or ".md" or ".markdown"))throw new InvalidDataException("صيغة المستند غير مدعومة");if(new FileInfo(path).Length>64L*1024*1024)throw new InvalidDataException("الملف يتجاوز حد القراءة النصية: 64 MB");if(extension==".doc")return ReadDoc(path);try{using var reader=new StreamReader(path,new UTF8Encoding(false,true),true);string text=reader.ReadToEnd();if(text.Length>32*1024*1024)throw new InvalidDataException("النص أكبر من حد العرض الآمن");return text.Length==0?Array.Empty<string>():text.Replace("\r\n","\n").Replace('\r','\n').Split('\n');}catch(DecoderFallbackException e){throw new InvalidDataException("ترميز النص غير مدعوم؛ احفظه UTF-8 أو UTF-16 مع علامة BOM",e);}}
 static string[] ReadDoc(string path){Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);using var input=File.OpenRead(path);var signature=new byte[8];if(input.Read(signature,0,8)!=8||!signature.SequenceEqual(new byte[]{0xd0,0xcf,0x11,0xe0,0xa1,0xb1,0x1a,0xe1}))throw new InvalidDataException("ليس ملف Word DOC ثنائيًا صالحًا؛ تغيير الامتداد وحده لا يحوّل المستند");input.Position=0;try{var extractor=new WordExtractor(input);long count=0;var result=new List<string>();foreach(string paragraph in extractor.ParagraphText){string text=WordExtractor.StripFields(paragraph).TrimEnd('\r','\n').Replace('\a','\t');text=new string(text.Where(c=>!char.IsControl(c)||c is '\t' or '\n').ToArray());count+=text.Length;if(count>32L*1024*1024)throw new InvalidDataException("نص DOC أكبر من حد العرض الآمن");result.Add(text);}return result.ToArray();}catch(Exception e) when(e is not OutOfMemoryException){throw new InvalidDataException("تعذرت قراءة DOC. تفاصيل خطأ القارئ: "+e.GetType().Name+": "+e.Message,e);}}
 public static List<PlainHeading> Headings(string path){var lines=Read(path);var result=new List<PlainHeading>();char fence='\0';int fenceLength=0;for(int i=0;i<lines.Length;i++){var block=Regex.Match(lines[i],"^ {0,3}(`{3,}|~{3,})(.*)$");if(block.Success){char ch=block.Groups[1].Value[0];int length=block.Groups[1].Length;if(fence=='\0'){fence=ch;fenceLength=length;}else if(ch==fence&&length>=fenceLength&&string.IsNullOrWhiteSpace(block.Groups[2].Value)){fence='\0';}continue;}if(fence!='\0')continue;var atx=Regex.Match(lines[i],"^ {0,3}(#{1,6})(?:[ \t]+|$)(.*)$");if(atx.Success){string text=Regex.Replace(atx.Groups[2].Value,"[ \t]+#+[ \t]*$","").Trim();if(text.Length>0)result.Add(new PlainHeading(i,atx.Groups[1].Length-1,text));continue;}if(i+1<lines.Length&&!string.IsNullOrWhiteSpace(lines[i])&&!lines[i].StartsWith("    ")&&!lines[i].StartsWith("\t")){var underline=Regex.Match(lines[i+1],"^ {0,3}(=+|-+)[ \t]*$");if(underline.Success){result.Add(new PlainHeading(i,underline.Groups[1].Value[0]=='='?0:1,lines[i].Trim()));i++;}}}return result;}
 public static void Verify(){DocReaderRegression.Verify();string dir=Path.Combine(Path.GetTempPath(),"AnsaryFormats-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string txt=Path.Combine(dir,"sample.txt"),unicode=Path.Combine(dir,"unicode.TXT"),md=Path.Combine(dir,"outline.md"),longMd=Path.Combine(dir,"copy.markdown");File.WriteAllText(txt,"العلم النافع والعمل\nسطر ثان",new UTF8Encoding(false));File.WriteAllText(unicode,"نص عربي",Encoding.Unicode);string markdown="# عنوان أول\n## عنوان ثان\n```\n# ليس عنوانا\n```\nقسم ثالث\n---\n";File.WriteAllText(md,markdown,new UTF8Encoding(false));File.WriteAllText(longMd,markdown);if(Core.Read(txt).Length!=2||Core.Read(unicode)[0]!="نص عربي"||!Core.Match(Core.Read(txt)[0],Core.Terms("العمل العلم")))throw new InvalidDataException("Text reading regression");var headings=Headings(md);if(headings.Count!=3||headings[0].Index!=0||headings[1].Level!=1||headings[2].Index!=5)throw new InvalidDataException("Markdown heading regression");string? fixture=Environment.GetEnvironmentVariable("ANSARY_DOC_FIXTURE");int count=4;if(!string.IsNullOrEmpty(fixture)){string target=Path.Combine(dir,"legacy.DOC");File.Copy(fixture,target);var paragraphs=Core.Read(target);if(paragraphs.Length!=14||paragraphs[0]!="This is a simple word document"||!paragraphs.Any(p=>Core.Match(p,Core.Terms("paragraphs number"))))throw new InvalidDataException("Binary DOC fixture regression");count++;}if(Core.Scan(dir,CancellationToken.None).Files.Count!=count||!Supported("legacy.DOC"))throw new InvalidDataException("Format discovery regression");}finally{Directory.Delete(dir,true);}}
}
